import * as React from "react";
import { SvgMpaIcon } from "../../../assets/icons";
import { MpaIcon } from "../../icon";
import "./Separator.scss";
import clsx from "clsx";
import { checkMpaIcon } from "../../utils/commonUtils";

export interface SeparatorProps {
  colour?: "link" | "black" | "white";
  separator?: React.ReactNode;
}

const Separator = ({ colour, separator }: SeparatorProps) => {
  return (
    <li
      className={clsx("breadcrumb-separator", {
        "breadcrumb-separator-black": colour === "black",
        "breadcrumb-separator-white": colour === "white",
      })}
    >

     {typeof separator === "string" && checkMpaIcon(separator) ? (
        <MpaIcon size={24} iconName={separator as keyof typeof SvgMpaIcon} />
      ) : (
        <div className="breadcrumb-separator-symbol">{separator}</div>
      )}
    </li>
  );
};

export default Separator;
